import{_ as o,o as t,c as r,a3 as d}from"./chunks/framework.CZHI6U0G.js";const p=JSON.parse('{"title":"Ledger selection — which ledger does myco open?","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/ledger-selection.md","filePath":"explanation/ledger-selection.md"}'),a={name:"explanation/ledger-selection.md"};function c(s,e,i,l,n,h){return t(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="ledger-selection-—-which-ledger-does-myco-open" tabindex="-1">Ledger selection — which ledger does <code>myco</code> open? <a class="header-anchor" href="#ledger-selection-—-which-ledger-does-myco-open" aria-label="Permalink to &quot;Ledger selection — which ledger does `myco` open?&quot;">​</a></h1><p>Myco can see many ledgers at once: every repo in the workspace has its own <code>project/</code> worktree, the index knows all of them, and one of them is designated the <em>org</em> ledger. This page explains how myco chooses which one a given invocation reads and writes — the mental model first, then the formal precedence table.</p><h2 id="the-layers" tabindex="-1">The layers <a class="header-anchor" href="#the-layers" aria-label="Permalink to &quot;The layers&quot;">​</a></h2><p>Four separate ideas are easy to conflate. Keep them apart:</p><ul><li><strong>Repo ledger</strong> — a repository&#39;s own <code>project/</code> worktree. When you <code>cd</code> into a myco-initialized repo, this is the ledger myco opens. Nothing needs configuring; discovery finds it.</li><li><strong>Index / universe</strong> — <code>repos.toml</code> under <code>$MYCO_HOME</code> is a disposable registry of known repos; the <em>universe</em> is lasius workspace clones ∪ registry entries. It is an address book, not data — delete it and myco loses nothing canonical.</li><li><strong>Org designation</strong> — one universe entry marked <code>ledger = &quot;org&quot;</code> (<code>[index] ledger = &quot;org&quot;</code> in its <code>myco.toml</code>, or <code>myco index add &lt;repo&gt; --org</code>). Its worktree is the fallback ledger for ledger-less repos and the last resort before error.</li><li><strong>Current selector</strong> — <em>your</em> sticky pointer in user-layer <code>~/.config/myco/myco.toml</code> (<code>[current]</code>). It answers &quot;which ledger&quot; when cwd alone doesn&#39;t say — from another repo, a plain folder, or anywhere at all.</li></ul><p>Two more surfaces sit alongside:</p><ul><li><strong>Directory pointer</strong> — a <code>.myco.toml</code> file in a plain (non-git) folder saying <code>ledger = &quot;…&quot;</code>. Found by walking up from cwd; ignored inside git repos, where it would be repo-controlled injection. Fallback semantics only — a repo&#39;s own ledger always beats it.</li><li><strong>Workspace</strong> — <code>[workspace] repos</code> glob patterns in user config selecting a <em>set</em> of universe repos. It scopes index-sourced views (<code>org-board</code>, <code>org-status</code>); it is not a ledger and does not affect single-ledger verbs.</li></ul><h2 id="scenarios" tabindex="-1">Scenarios <a class="header-anchor" href="#scenarios" aria-label="Permalink to &quot;Scenarios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You are…</th><th>What myco does</th></tr></thead><tbody><tr><td>Inside a repo with its own <code>project/</code></td><td>Opens that repo&#39;s ledger — the default, no config needed.</td></tr><tr><td>Inside a ledger-less repo</td><td>Falls through to the org-designated ledger.</td></tr><tr><td>In a plain folder with a <code>.myco.toml</code> pointer</td><td>Opens the pointer&#39;s target — but only if nothing closer claimed the cwd first.</td></tr><tr><td>Anywhere, with <code>[current]</code> set</td><td><code>mode = &quot;always&quot;</code> pins that ledger everywhere; <code>mode = &quot;backup&quot;</code> answers only when discovery finds nothing (still beating the org fallback).</td></tr><tr><td>Passing <code>--dir</code>, <code>--root</code>, or <code>MYCO_LEDGER</code></td><td>That explicit target wins over everything, every time.</td></tr><tr><td>Running <code>org-board</code> / <code>org-status</code></td><td>Reads the index universe — filtered to <code>[workspace]</code> when configured. Bypasses ledger selection entirely.</td></tr></tbody></table><h2 id="precedence-—-the-formal-order" tabindex="-1">Precedence — the formal order <a class="header-anchor" href="#precedence-—-the-formal-order" aria-label="Permalink to &quot;Precedence — the formal order&quot;">​</a></h2><p>First match wins. Rows 1–2 are explicit per-invocation flags; rows 3–4 are selectors that answer <em>before</em> looking at where you are; rows 5–7 are ordinary cwd discovery; rows 8–9 are late selectors; row 10 is the org fallback.</p><table tabindex="0"><thead><tr><th>#</th><th>Source</th><th>Applies when</th><th>Yields</th></tr></thead><tbody><tr><td>1</td><td><code>--dir &lt;PATH&gt;</code></td><td>always</td><td>the worktree path directly</td></tr><tr><td>2</td><td><code>--root &lt;PATH&gt;</code></td><td>always (loses to <code>--dir</code>)</td><td><code>&lt;root&gt;/project</code> or repo <code>project_dir</code></td></tr><tr><td>3</td><td><code>MYCO_LEDGER=&lt;target&gt;</code></td><td>target ≠ <code>repo</code></td><td>resolved target; unresolvable → hard error</td></tr><tr><td>4</td><td><code>[current] mode=&quot;always&quot;</code></td><td><code>ledger</code> ≠ <code>repo</code></td><td>resolved target; unresolvable → hard error</td></tr><tr><td>5</td><td>cwd inside a <code>project/</code> worktree</td><td>cwd resolves to a ledger</td><td>that worktree</td></tr><tr><td>6</td><td>repo <code>myco.toml project_dir</code></td><td>cwd inside a repo</td><td><code>&lt;repo&gt;/&lt;project_dir&gt;</code></td></tr><tr><td>7</td><td>ancestor <code>project/</code> walk</td><td>qualifying <code>project/</code> upward</td><td>that worktree</td></tr><tr><td>8</td><td><code>.myco.toml</code> directory pointer</td><td>nearest pointer, not inside a git repo</td><td>declared ledger</td></tr><tr><td>9</td><td><code>[current] mode=&quot;backup&quot;</code> (+ env <code>MYCO_LEDGER_SCOPE=backup</code>)</td><td><code>ledger</code> ≠ <code>repo</code></td><td>resolved target; unresolvable → hard error</td></tr><tr><td>10</td><td>org fallback</td><td>an org designation exists</td><td>org worktree</td></tr><tr><td>11</td><td>—</td><td>nothing matched</td><td>error</td></tr></tbody></table><p>Notes that matter:</p><ul><li><code>MYCO_LEDGER_SCOPE</code> defaults to <code>always</code> when <code>MYCO_LEDGER</code> is set; <code>MYCO_LEDGER=repo</code> disables the env override entirely.</li><li>Rows 5–7 only match when they yield a ledger — a ledger-less repo context falls through.</li><li>Row 8 sits after repo discovery deliberately: a repo&#39;s own ledger always beats a pointer file.</li><li>Row 4 (<code>always</code>) beats row 8: an explicit global pin is stronger than a directory hint.</li><li><strong>Stale targets hard-error in every mode</strong> — a moved repo or removed org designation fails loudly rather than silently falling back. The escape hatch is <code>MYCO_LEDGER=repo &lt;cmd&gt;</code> (env row 3 beats the persisted row 4, so <code>myco current clear</code> itself would hit the same wall).</li></ul><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p><code>[current].ledger</code>, <code>MYCO_LEDGER</code>, pointer files, and <code>current use</code>/<code>workspace</code>-adjacent resolution share one vocabulary:</p><ul><li><code>repo</code> — disable the selector (the inert default).</li><li><code>org</code> — the index-designated org ledger.</li><li><code>&lt;name&gt;</code> — a universe repo name (lasius clone or registry entry).</li><li><code>&lt;/abs/path&gt;</code> — a ledger worktree directly, or a repo root resolved like <code>--root</code>.</li><li><code>name:&lt;repo&gt;</code> — forces universe-name lookup, disambiguating repos literally named <code>repo</code> or <code>org</code>.</li></ul><p>Ambiguous names hard-error listing the candidates.</p><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p>CLI, <code>myco ui</code>, <code>serve</code>, <code>batch</code>, and the driver&#39;s <code>cli.&lt;verb&gt;</code> queries all share <code>myco-ops</code> discovery — the selector applies uniformly, <code>--json</code> everywhere. The exceptions are deliberate: index-sourced views (<code>org-board</code>, <code>org-status</code>) name their source explicitly and bypass single-ledger selection; <code>[workspace]</code> scopes them instead. Index bookkeeping verbs (<code>index add/remove</code>) also stay strict — a pinned ledger must never hijack repo registration.</p>',20)])])}const u=o(a,[["render",c]]);export{p as __pageData,u as default};
